package com.bplus.share;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Inbound share data is displayed and staged only. User chooses destination and presses Send. */
public final class ReceiveShareActivity extends Activity{
 private LinearLayout box,footer;private TextView next;private JSONObject selected;private final Map<String,View> targetRows=new HashMap<>();private final Map<String,TextView> radios=new HashMap<>(),states=new HashMap<>();private final java.util.concurrent.ExecutorService checks=java.util.concurrent.Executors.newFixedThreadPool(3);private int checkGeneration;private boolean choosing;private TextView status;private final ArrayList<JSONObject> files=new ArrayList<>();private final ArrayList<File> staged=new ArrayList<>();private String text="";private boolean committed;private volatile boolean cancelled;
 protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.incoming_share),true,null));ScrollView scroll=new ScrollView(this);box=Ui.col(this);Ui.pad(box,20,16,20,16,this);scroll.addView(box);root.addView(scroll,Ui.lpW1());footer=Ui.col(this);Ui.pad(footer,20,12,20,16,this);footer.setBackground(Ui.roundBorder(Ui.bg,Ui.border,0,this));root.addView(footer,Ui.lp(-1,-2));footer.setVisibility(View.GONE);next=Ui.cta(this,getString(R.string.share_select_device));footer.addView(next,Ui.lp(-1,-2));next.setEnabled(false);next.setAlpha(.45f);next.setOnClickListener(v->confirmTarget());TextView cancel=Ui.t(this,getString(R.string.cancel),13,Ui.dim,App.cairoSB);cancel.setGravity(Gravity.CENTER);cancel.setMinHeight(Ui.dp(this,44));footer.addView(cancel,Ui.lp(-1,-2));cancel.setOnClickListener(v->finish());
 status=Ui.t(this,getString(R.string.share_loading),15,Ui.text,App.cairoSB);box.addView(status);setContentView(root);Intent incoming=getIntent();if(!Intent.ACTION_SEND.equals(incoming.getAction())&&!Intent.ACTION_SEND_MULTIPLE.equals(incoming.getAction())){finish();return;}new Thread(()->load(incoming)).start();}
 @SuppressWarnings("deprecation") private void load(Intent i){try{CharSequence body=i.getCharSequenceExtra(Intent.EXTRA_TEXT);text=body==null?"":body.toString();if(!ImportRules.text(text))throw new IOException(getString(R.string.share_text_limit));LinkedHashSet<Uri> uris=new LinkedHashSet<>();if(Intent.ACTION_SEND_MULTIPLE.equals(i.getAction())){ArrayList<Uri> list=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)uris.addAll(list);}else{Uri uri=i.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null)uris.add(uri);}if(i.getClipData()!=null)for(int n=0;n<i.getClipData().getItemCount();n++){Uri u=i.getClipData().getItemAt(n).getUri();if(u!=null)uris.add(u);}if(!ImportRules.count(uris.size()))throw new IOException(getString(R.string.share_file_limit));long total=0;File dir=new File(getFilesDir(),"shared");if(!dir.exists()&&!dir.mkdirs())throw new IOException();for(Uri uri:uris){if(cancelled)return;if(!ImportRules.source(uri.getScheme(),uri.getAuthority(),getPackageName()))throw new IOException(getString(R.string.share_uri_refused));String name="shared-file";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}if(name==null)name="shared-file";name=new File(name.replace('\\','/')).getName();if(name.isEmpty())name="shared-file";File local=new File(dir,UUID.randomUUID()+"-"+name);synchronized(staged){staged.add(local);}long size=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(local)){if(in==null)throw new IOException();byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0){if(cancelled)throw new IOException();size+=n;total+=n;if(!ImportRules.bytes(size,total))throw new IOException(getString(R.string.share_size_limit));out.write(buffer,0,n);}}Uri saved=Uri.parse("content://"+getPackageName()+".files/shared/"+Uri.encode(local.getName()));files.add(new JSONObject().put("uri",saved.toString()).put("name",name).put("size",size));}if(text.isEmpty()&&files.isEmpty())throw new IOException(getString(R.string.share_empty));runOnUiThread(this::choose);}catch(Exception e){cleanup();runOnUiThread(()->{if(!isFinishing()){status.setText(getString(R.string.share_import_failed)+"\n"+(e.getMessage()==null?"":e.getMessage()));}});}finally{if(cancelled)cleanup();}}
 private void choose(){if(cancelled||isFinishing()){cleanup();return;}choosing=true;box.removeAllViews();targetRows.clear();radios.clear();states.clear();selected=null;
  LinearLayout summary=Ui.col(this);summary.setBackground(Ui.roundBorder(Ui.card,Ui.border,16,this));Ui.pad(summary,18,16,18,16,this);box.addView(summary,Ui.lp(-1,-2));summary.addView(Ui.t(this,getString(R.string.share_ready_count,files.size(),text.isEmpty()?0:1),16,Ui.text,App.cairoB));long total=0;
  for(JSONObject f:files){total+=f.optLong("size");LinearLayout row=Ui.row(this);Ui.pad(row,0,10,0,0,this);TextView icon=Ui.t(this,"▧",24,Ui.accent,App.cairoSB);icon.setGravity(Gravity.CENTER);row.addView(icon,Ui.lp(Ui.dp(this,44),Ui.dp(this,48)));LinearLayout meta=Ui.col(this);TextView name=Ui.t(this,f.optString("name"),13,Ui.text,App.cairoSB);name.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG);meta.addView(name,Ui.lp(-1,-2));meta.addView(Ui.t(this,Ui.fmtSize(f.optLong("size")),12,Ui.dim,App.cairo));row.addView(meta,Ui.lpw(1));summary.addView(row);}
  if(files.size()>1)summary.addView(Ui.t(this,getString(R.string.share_total_size,Ui.fmtSize(total)),12,Ui.dim,App.cairoSB));if(!text.isEmpty()){TextView body=Ui.t(this,text,13,Ui.text,App.cairo);Ui.pad(body,0,10,0,0,this);body.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG);summary.addView(body);}
  TextView label=Ui.t(this,getString(R.string.share_select_device),16,Ui.text,App.cairoB);Ui.pad(label,0,26,0,10,this);box.addView(label);JSONArray peers=Store.peers();
  for(int n=0;n<peers.length();n++){JSONObject peer=peers.optJSONObject(n);if(peer==null)continue;String id=peer.optString("id");LinearLayout row=Ui.row(this);row.setBackground(Ui.roundBorder(Ui.card,Ui.border,16,this));Ui.pad(row,14,14,14,14,this);LinearLayout.LayoutParams lp=Ui.lp(-1,-2);lp.bottomMargin=Ui.dp(this,10);box.addView(row,lp);row.addView(Profile.avatar(this,peer,48));LinearLayout meta=Ui.col(this);Ui.pad(meta,12,0,12,0,this);TextView name=Ui.t(this,peer.optString("name"),16,Ui.text,App.cairoB);name.setSingleLine();name.setEllipsize(android.text.TextUtils.TruncateAt.END);meta.addView(name,Ui.lp(-1,-2));LinearLayout platform=Ui.row(this);String kind=SharePickerRules.platform(peer.optString("platform"));ImageView type=new ImageView(this);type.setImageDrawable(new DeviceKindIcon(kind,Ui.dim));platform.addView(type,Ui.lp(Ui.dp(this,16),Ui.dp(this,16)));TextView typeName=Ui.t(this,getString(kind.equals("computer")?R.string.share_kind_computer:kind.equals("phone")?R.string.share_kind_phone:R.string.share_kind_device),11,Ui.dim,App.cairoSB);Ui.pad(typeName,5,0,5,0,this);platform.addView(typeName);meta.addView(platform);TextView state=Ui.t(this,getString(R.string.share_checking_peer),12,Ui.dim,App.cairoSB);meta.addView(state);states.put(id,state);row.addView(meta,Ui.lpw(1));TextView radio=Ui.t(this,"○",24,Ui.dim,App.cairoSB);radio.setGravity(Gravity.CENTER);row.addView(radio,Ui.lp(Ui.dp(this,36),Ui.dp(this,44)));radios.put(id,radio);targetRows.put(id,row);row.setContentDescription(peer.optString("name"));row.setOnClickListener(v->select(peer));}
  if(peers.length()==0)box.addView(Ui.t(this,getString(R.string.no_chats),14,Ui.dim,App.cairoSB));TextView note=Ui.t(this,getString(R.string.share_select_note),12,Ui.dim,App.cairo);Ui.pad(note,0,8,0,12,this);box.addView(note);footer.setVisibility(View.VISIBLE);refreshReachability();
 }
 private void select(JSONObject peer){if(committed||cancelled)return;selected=peer;for(String id:targetRows.keySet()){boolean on=id.equals(peer.optString("id"));targetRows.get(id).setBackground(Ui.roundBorder(on?Ui.field:Ui.card,on?Ui.accent:Ui.border,16,this));radios.get(id).setText(on?"◉":"○");radios.get(id).setTextColor(on?Ui.accent:Ui.dim);targetRows.get(id).setSelected(on);}next.setText(getString(R.string.share_continue_to,peer.optString("name")));next.setEnabled(true);next.setAlpha(1f);}
 private void confirmTarget(){if(selected==null||committed||cancelled)return;JSONObject peer=Store.peerById(selected.optString("id"));if(peer==null){android.widget.Toast.makeText(this,R.string.not_paired,1).show();return;}new AppDialog(this).setTitle(R.string.incoming_share).setMessage(getString(R.string.share_target_confirm,peer.optString("name"),files.size(),text.isEmpty()?0:1)).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(d,k)->send(peer)).show();}
 private void refreshReachability(){if(!choosing||committed||cancelled)return;final int generation=++checkGeneration;for(String id:states.keySet()){TextView state=states.get(id);state.setText(R.string.share_checking_peer);state.setTextColor(Ui.dim);JSONObject peer=Store.peerById(id);if(peer==null){state.setText(R.string.not_paired);continue;}checks.execute(()->{JSONObject reply=Net.ping(peer.optString("ip"),peer.optInt("port",Store.PORT),peer.optString("token"));boolean on=SharePickerRules.available(id,reply==null?"":reply.optString("id"));runOnUiThread(()->{if(cancelled||isFinishing()||committed||generation!=checkGeneration)return;boolean paired=Store.peerById(id)!=null;state.setText(getString(!paired?R.string.not_paired:on?R.string.share_available_peer:R.string.share_unreachable_peer));state.setTextColor(on&&paired?Ui.green:Ui.dim);});});}}
 @Override protected void onResume(){super.onResume();if(choosing)refreshReachability();}
 @Override protected void onPause(){checkGeneration++;super.onPause();}
 private void send(JSONObject peer){if(committed||cancelled)return;JSONObject live=Store.peerById(peer.optString("id"));if(live==null){android.widget.Toast.makeText(this,R.string.not_paired,1).show();return;}committed=true;choosing=false;checkGeneration++;footer.setVisibility(View.GONE);box.removeAllViews();box.addView(status);status.setText(R.string.sending);new Thread(()->{int ok=0,count=files.size()+(text.isEmpty()?0:1);if(!text.isEmpty()&&TransferService.sendTextToPeer(live,text))ok++;for(JSONObject m:files)if(TransferService.sendToPeer(live,Uri.parse(m.optString("uri")),m.optString("name"),m.optLong("size")))ok++;final int sent=ok;runOnUiThread(()->{status.setText(getString(R.string.send_items_result,sent,count));TextView open=Ui.cta(this,getString(R.string.share_open_chat));box.addView(open);open.setOnClickListener(v->{startActivity(new Intent(this,ChatActivity.class).putExtra("peer",peer.optString("id")));finish();});});}).start();}
 private void cleanup(){if(committed)return;synchronized(staged){for(File f:staged)f.delete();}}
 protected void onDestroy(){cancelled=true;checkGeneration++;checks.shutdownNow();cleanup();super.onDestroy();}
}
